#!/usr/bin/env bash
# Converts packaging/macos/AppIcon.iconset/ (generated by
# packaging/icon/generate_icons.py) into a single .icns file.
#
# Prefers `iconutil` (built into every macOS host, no extra dependency —
# this is what build-macos.sh actually uses in CI/production builds).
# Falls back to `png2icns` (from the `icnsutils`/`libicns` package) only
# so this step can be exercised/tested on non-macOS dev machines too —
# never used for a real release build, since build-macos.sh only ever
# runs on macOS.
set -euo pipefail

# make_icns <iconset_dir> <out_icns_path>
make_icns() {
    local iconset_dir="$1"
    local out_icns="$2"

    if command -v iconutil >/dev/null 2>&1; then
        iconutil -c icns "$iconset_dir" -o "$out_icns"
        return 0
    fi

    if command -v png2icns >/dev/null 2>&1; then
        echo "Warning: 'iconutil' not found (not on macOS?) — falling back" >&2
        echo "to 'png2icns' for local testing. Real builds must run on" >&2
        echo "macOS, where build-macos.sh uses 'iconutil' instead." >&2
        # png2icns only understands a handful of fixed square sizes, not
        # the full Apple iconset naming scheme — feed it the "@1x" files.
        png2icns "$out_icns" \
            "$iconset_dir/icon_16x16.png" \
            "$iconset_dir/icon_32x32.png" \
            "$iconset_dir/icon_128x128.png" \
            "$iconset_dir/icon_256x256.png" \
            "$iconset_dir/icon_512x512.png"
        return 0
    fi

    echo "Error: neither 'iconutil' (macOS) nor 'png2icns' (icnsutils/libicns," >&2
    echo "for local testing only) found. Install one of them." >&2
    return 1
}
